chmod 0755 /var/www/nginx-6700
printf 'nginx on %s\n' "$NODE_NAME" > /var/www/nginx-6700/index.html
chmod 0644 /var/www/nginx-6700/index.html
cat > /etc/nginx/conf.d/benchmark-6700.conf <<'ANTRIEB_NGINX_6700'
server {
    listen 6700 default_server;
    listen [::]:6700 default_server;
    server_name _;
    root /var/www/nginx-6700;
    index index.html;

    location / {
        try_files $uri $uri/ =404;
    }
}
